# scratch-only: evaluate all target formulas with `formulas` and compare to an independent pandas-free computation
import sys, math, statistics, formulas
from openpyxl import load_workbook
orig, filled, missing = sys.argv[1], sys.argv[2], sys.argv[3]
xl = formulas.ExcelModel().loads(filled).finish(); sol = xl.calculate()
got = {}
for k, v in sol.items():
    ku = k.upper()
    if "TASK'!" in ku and ":" not in ku.split("!")[1]:
        x = v.value[0][0] if hasattr(v, "value") else v
        got[ku.split("!")[1]] = x
wb = load_workbook(orig); t, d = wb["Task"], wb["Data"]
hdr = {d.cell(1, c).value: c for c in range(1, d.max_column + 1)}
ids = {d.cell(r, 1).value: r for r in range(2, d.max_row + 1)}
from openpyxl.utils import get_column_letter as L
bad = n = 0
def chk(ref, e):
    global bad, n
    n += 1
    g = got.get(ref)
    g = None if g in ("", None) or (isinstance(g, float) and math.isnan(g)) else g
    if isinstance(g, str): bad += 1; print("ERR", ref, g); return
    if (e is None) != (g is None) or (e is not None and not math.isclose(float(g), e, abs_tol=1e-9)):
        bad += 1; print("MISMATCH", ref, g, e)
grp = {c: t.cell(9, c).value for c in range(3, 13)}
for i, r in enumerate(range(11, 21)):
    vals = {}
    for c in range(3, 13):
        v = d.cell(ids[t.cell(r, 1).value], hdr[t.cell(10, c).value]).value
        if v is None and missing == "zero": v = 0.0
        vals[c] = v; chk(f"{L(c)}{r}", v)
    s = L(2 + i); m = {}
    for g, mr, sr in (("Control", 24, 25), ("Treated", 26, 27)):
        xs = [vals[c] for c in vals if grp[c] == g and vals[c] is not None]
        m[g] = statistics.mean(xs) if xs else None
        chk(f"{s}{mr}", m[g]); chk(f"{s}{sr}", statistics.stdev(xs) if len(xs) > 1 else None)
    l2 = m["Treated"] - m["Control"]
    chk(f"D{32+i}", l2); chk(f"C{32+i}", 2 ** l2)
print("checked", n, "bad", bad)
EOF
cd run1; ../venv/bin/python ../sim_check.py orig.xlsx protein_expression.xlsx exclude 2>/dev/null

